def transform(grid):
    from collections import deque, defaultdict

    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    g = [row[:] for row in grid]

    # A long thin or L-shaped object serves as the color key.
    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            pts = []
            while q:
                y, x = q.pop()
                pts.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, pts))

    # Identify a distinctive long line / corner marker color.
    key = None
    best = -1
    for color, pts in comps:
        ys = [p[0] for p in pts]
        xs = [p[1] for p in pts]
        hh, ww = max(ys)-min(ys)+1, max(xs)-min(xs)+1
        score = 0
        if hh == 1 or ww == 1:
            score = len(pts)
        elif hh >= 3 and ww >= 3 and len(pts) >= hh + ww - 2:
            score = len(pts) + 2
        if score > best:
            best, key = score, color

    # Compare component silhouettes (allow rotations/reflections) and recolor
    # the isolated copy of a repeated silhouette to the marker color.
    def norm(pts):
        y0 = min(y for y,x in pts)
        x0 = min(x for y,x in pts)
        return frozenset((y-y0, x-x0) for y,x in pts)

    groups = defaultdict(list)
    for color, pts in comps:
        if color != key:
            groups[norm(pts)].append((color, pts))

    chosen = None
    for shape, items in groups.items():
        if len(items) > 1 and len(set(c for c,p in items)) > 1:
            # Recolor a copy differing in color from the others.
            chosen = items[-1][1]
            break

    if chosen is not None and key is not None:
        for r, c in chosen:
            g[r][c] = key
    return g
